import java.util.Scanner;
import java.math.BigInteger;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int total_n = scanner.nextInt();
        int modulus = scanner.nextInt();

        if (total_n == 1) {
            System.out.println(0);
            return;
        }

        // Helper method for factorial
        java.util.Map<Integer, BigInteger> factorialCache = new java.util.HashMap<>();
        BigInteger factorial(int n) {
            if (factorialCache.containsKey(n)) {
                return factorialCache.get(n);
            }
            BigInteger result = BigInteger.ONE;
            for (int i = 2; i <= n; i++) {
                result = result.multiply(BigInteger.valueOf(i));
            }
            factorialCache.put(n, result);
            return result;
        }

        // Helper method for permutation
        long getPerm(int n, int k) {
            return factorial(n).divide(factorial(n - k)).longValue();
        }

        int[] sequence = {1};
        long totalSum = 0;

        for (int i = 2; i <= total_n; i++) {
            int size = ((i - 1) * i) / 2 + 1;
            int[] newSeq = new int[size];

            int[] prefixSum = new int[sequence.length + 1];
            for (int idx = sequence.length - 1; idx >= 0; idx--) {
                prefixSum[idx] = (prefixSum[idx + 1] + sequence[idx]) % modulus;
            }

            for (int w = 0; w < size; w++) {
                int leftIdx = Math.max(0, w + 1 - i);
                int rightIdx = Math.min(sequence.length - 1, w);
                int val = prefixSum[leftIdx] - prefixSum[rightIdx + 1];
                newSeq[w] = ((val % modulus) + modulus) % modulus;
            }

            int[] eArr = new int[prefixSum.length];
            int[] fArr = new int[prefixSum.length];

            eArr[0] = 0;
            fArr[0] = 0;
            for (int w = 0; w < prefixSum.length - 1; w++) {
                eArr[w + 1] = (eArr[w] + prefixSum[w]) % modulus;
                fArr[w + 1] = (fArr[w] - w * prefixSum[w]) % modulus;
                eArr[w + 1] = ((eArr[w + 1] % modulus) + modulus) % modulus;
                fArr[w + 1] = ((fArr[w + 1] % modulus) + modulus) % modulus;
            }

            int R_idx = sequence.length;
            long temp_b_value = 0;

            int startIdx1 = Math.max(0, sequence.length - i);
            for (int jj = startIdx1; jj < sequence.length - 1; jj++) {
                int L_idx = jj + 2;
                long numerator = ((long)(eArr[R_idx] - eArr[L_idx]) * (i + 1 + jj) + (fArr[R_idx] - fArr[L_idx])) % modulus;
                numerator = (numerator + modulus) % modulus;
                long val = (numerator * sequence[jj]) % modulus;
                temp_b_value = (temp_b_value + val) % modulus;
            }

            for (int jj = 0; jj < sequence.length - i; jj++) {
                int L_idx = jj + 2;
                int R_idx2 = i + jj;
                long numerator = ((long)(eArr[R_idx2 + 1] - eArr[L_idx]) * (i + 1 + jj) + (fArr[R_idx2 + 1] - fArr[L_idx])) % modulus;
                numerator = (numerator + modulus) % modulus;
                long val = (numerator * sequence[jj]) % modulus;
                temp_b_value = (temp_b_value + val) % modulus;
            }

            long perm = getPerm(total_n, total_n - i);
            totalSum = (totalSum + (temp_b_value * perm) % modulus) % modulus;

            sequence = newSeq;
        }

        System.out.println(totalSum % modulus);
        scanner.close();
    }
}
